-- PostgreSQL baseline for Mi Ladwani.
--
-- The schema ran on MySQL from Sep to Oct 2026; PostgreSQL is now the final
-- target. This single migration replaces the six MySQL migrations
-- (20260910163143_init .. 20261009110000_interest_groups) and creates the
-- whole schema as it stood at the end of that history. It was generated with
--   npx prisma migrate diff --from-empty \
--     --to-schema-datamodel prisma/schema.prisma --script
-- plus the hand-written parts marked "Not generated by Prisma" below.
--
-- A database that was built by the old MySQL migrations cannot be upgraded
-- by this file: build a fresh PostgreSQL database with it, then copy the
-- data across with scripts/migrate-mysql-to-postgres.ts (see MIGRATION.md).

-- ─────────────────────────────────────────────────────────────────
-- Not generated by Prisma: extensions.
--
-- citext  — users.email is CITEXT (case-insensitive unique + lookups, as
--           under MySQL's utf8mb4_unicode_ci collation).
-- btree_gist — lets the bookings exclusion constraint at the end of this
--           file combine equality on "assetId" with a range overlap.
--
-- Both are "trusted" extensions (PostgreSQL 13+), so the database owner can
-- create them without superuser rights. Most managed PostgreSQL providers
-- allow both; check yours before the first deploy.
-- ─────────────────────────────────────────────────────────────────
CREATE EXTENSION IF NOT EXISTS citext;
CREATE EXTENSION IF NOT EXISTS btree_gist;

